Composite Class with Multiple Shapes (Draw a Monster)
We can use these classes like building blocks to create small images. This Monster (pictured below) is made up of two Shapes (dots) and four Triangles.



Monster


Here’s the implementation. Notice that the monster does not need to inherit from Shape because it has lots of Shapes in it that can draw themselves.
class Monster():
  def __init__(self, x, y, size):
    self.teeth = [
      Triangle(x, y, size),
      Triangle(x+size, y, size),
      Triangle(x+size*2, y, size),
      Triangle(x+size*3, y, size),
    ]
    self.eyes = [
      Shape(x+size, y+size),
      Shape(x+size*3, y+size),
    ]

  def draw(self):
    for tooth in self.teeth:
      tooth.draw()
    for eye in self.eyes:
      eye.draw()

m = Monster(-200, 0, 20)
m.draw()

Collision with the top of the floor
Here’s the final Box class with a function for checking collision with the top.
# engine.py
class Box:
    def __init__(
        self, x: float, y: float, w: float, h: float, col: int, filled=False, phys=False
    ):
        self.x = x
        self.y = y
        self.w = w
        self.h = h
        self.col = col
        self.filled = filled
        self.phys = Physics() if phys else None

    def is_colliding_top(self, box):
        if (
            (box.y + box.h &gt;= self.y and box.y &lt;= self.y)
            and box.phys
            and (
                (self.x &lt;= box.x + box.w and self.x + self.w &gt;= box.x + box.w)
                or (self.x &lt;= box.x and self.x + self.w &gt;= box.x)
            )
        ):
            if box.phys.dy &gt; 0:
                # knockback
                box.phys.ground()
                box.y = self.y - box.h - GRAVITY
            return True
        return False

    def fall(self, collider: Callable[[any], bool]):
        if self.phys:
            # call the collider to see if the object can fall
            self.phys.fall(collider(self))
            self.y += self.phys.dy
            # call the collider a second time for knockback
            collider(self)

    def draw(self):
        if self.phys:
            print(self.phys.state_machine.state)
        if self.filled:
            pyxel.rect(self.x, self.y, self.w, self.h, self.col)
        else:
            pyxel.rectb(self.x, self.y, self.w, self.h, self.col)
